mapper.select:
SELECT s.id, s.user_id, s.student_no, s.school_id, s.name, s.gender, s.birth_date, s.enrollment_date, s.status, s.created_at, s.updated_at FROM student s WHERE s.deleted = 0
AND s.school_id = #{request.schoolId}
AND s.student_no LIKE CONCAT('%', #{request.studentNo}, '%')
AND s.name LIKE CONCAT('%', #{request.name}, '%')
AND s.gender = #{request.gender}
AND s.status = #{request.status}
AND EXISTS ( SELECT 1 FROM class_student cs WHERE cs.student_id = s.id AND cs.class_id = #{request.classId} )
ORDER BY ${request.orderBy}
ASC
DESC
ORDER BY s.created_at DESC
